const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let num = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            num = num * 10 + (buffer[offset] - 48);
            offset++;
        }
        return num;
    }

    const n = nextInt();
    if (n === null) return;

    const L = new Float64Array(n);
    for (let k = 0; k < n; k++) {
        L[k] = nextInt();
    }

    let i = 0;
    let j = n - 1;
    let sumL = L[0];
    let sumR = L[n - 1];
    let ops = 0;

    while (i < j) {
        if (sumL === sumR) {
            i++;
            j--;
            sumL = L[i];
            sumR = L[j];
        } else if (sumL < sumR) {
            i++;
            sumL += L[i];
            ops++;
        } else {
            j--;
            sumR += L[j];
            ops++;
        }
    }

    process.stdout.write(ops.toString() + '\n');
}

solve();
